-- Production Import: replace local interests + ages + videos with production data
-- Source: customer-provided videos.json (767 rows) + vedio_interst.txt (9 interests)
-- ════════════════════════════════════════════════════════════════════════════
-- ⚠️ DESTRUCTIVE: wipes existing videos, interests, and ages.
-- Foreign-key cleanup:
--   - children.age_id is set to NULL (parents can re-select after import)
--   - child_interests cascades automatically (interest delete on cascade)
--   - playlist_videos cascades when their video rows are deleted

begin;

-- 1. Clean dependent rows first
update public.children set age_id = null;
delete from public.playlist_videos;
delete from public.videos;
delete from public.child_interests;

-- 2. Wipe + reseed ages (with explicit IDs to match production)
delete from public.ages;
alter sequence public.ages_id_seq restart with 1;

